<template>
  <div class="ai-workspace">
    <header class="page-header">
      <div class="header-copy">
        <span class="header-icon"><Sparkles :size="21" /></span>
        <div><div class="title-line"><h2>AI 工作台</h2><span>独立栏目</span></div><p>主动导入、独立解析和文档问答，不参与分享、转存或云端迁移</p></div>
      </div>
      <div class="header-actions"><el-button @click="localToolsVisible=true"><Wrench :size="15" />本地能力</el-button><el-button @click="openProviderDialog"><Settings2 :size="15" />模型设置</el-button><el-button type="primary" :loading="importing" @click="selectAndImport"><FilePlus2 :size="15" />导入文件</el-button></div>
    </header>

    <nav class="workspace-tabs">
      <button v-for="tab in tabs" :key="tab.key" :class="{ active: activeView === tab.key }" @click="activeView = tab.key"><component :is="tab.icon" :size="15" />{{ tab.label }}<span v-if="tab.count !== undefined" class="tab-count">{{ tab.count }}</span></button>
    </nav>

    <main>
      <template v-if="activeView === 'overview'">
        <section class="hero">
          <div><span class="kicker">PANLITE AI CORE</span><h3>让文件变成可以直接提问的知识</h3><p>PDF、Word、Excel、PPT 和文本文件仅在你主动导入后建立本地索引，原文件不会被移动或删除。</p><div class="hero-actions"><button class="primary" @click="activeView = 'ask'"><MessagesSquare :size="16" />开始文档问答</button><button @click="selectAndImport"><UploadCloud :size="16" />导入文件</button></div></div>
          <aside><span class="model-orb" :class="{ ready: providerConfigured }"><BrainCircuit :size="31" /></span><strong>{{ providerConfigured ? providerLabel : '模型尚未配置' }}</strong><small>{{ providerConfigured ? providerConfig.model : '支持 OpenAI 兼容接口和 Ollama' }}</small><button @click="openProviderDialog">{{ providerConfigured ? '检查配置' : '立即配置' }}</button></aside>
        </section>
        <section class="stats"><article><Files :size="18" /><strong>{{ documents.length }}</strong><span>已导入文档</span></article><article><CircleCheckBig :size="18" /><strong>{{ readyDocuments.length }}</strong><span>可参与问答</span></article><article><Puzzle :size="18" /><strong>{{ awaitingCount }}</strong><span>等待能力包</span></article><article><Activity :size="18" /><strong>{{ tasks.length }}</strong><span>AI 任务</span></article></section>
        <section class="panel"><div class="panel-heading"><div><span class="kicker">文件理解</span><h3>当前能力</h3></div><small>重型能力按需加载，控制安装包体积</small></div><div class="capability-grid"><article v-for="item in capabilities" :key="item.name"><span class="capability-icon"><component :is="item.icon" :size="19" /></span><span class="capability-state" :class="{ ready: item.available }">{{ item.available ? '基础可用' : '规划中' }}</span><h4>{{ item.name }}</h4><p>{{ item.description }}</p><div><small v-for="format in item.formats" :key="format">{{ format }}</small></div></article></div></section>
        <section class="panel"><div class="panel-heading"><div><span class="kicker">最近内容</span><h3>最近导入</h3></div><button class="link-button" @click="activeView = 'documents'">查看全部 <ArrowRight :size="14" /></button></div><div v-if="documents.length" class="recent-grid"><button v-for="document in documents.slice(0,4)" :key="document.id" @click="showDocument(document)"><span class="file-icon"><FileText :size="17" /></span><span><strong>{{ document.name }}</strong><small>{{ formatFileSize(document.size) }} · {{ statusLabel(document.status) }}</small></span><ChevronRight :size="15" /></button></div><div v-else class="empty"><Library :size="30" /><strong>还没有导入文件</strong><span>先导入一份文档，再开始提问。</span></div></section>
      </template>

      <section v-else-if="activeView === 'ask'" class="chat-layout">
        <aside class="scope-panel">
          <div class="conversation-heading"><div><span class="kicker">对话记录</span><h3>我的对话</h3></div><button title="新建对话" @click="newConversation"><Plus :size="14" /></button></div>
          <div class="conversation-search"><Search :size="13" /><input v-model="conversationSearch" placeholder="搜索标题和消息" @input="searchConversations" /><X v-if="conversationSearch" :size="12" @click="clearConversationSearch" /></div>
          <div class="conversation-list">
            <div v-for="conversation in displayedConversations" :key="conversation.id" class="conversation-item" :class="{ active: activeConversationId === conversation.id }">
              <button class="conversation-main" @click="selectConversation(conversation.id)"><MessageCircle :size="14" /><span><strong>{{ conversation.title }}</strong><small v-if="conversation.snippet">{{ conversation.snippet }}</small></span></button>
              <button title="重命名" @click="renameConversation(conversation)"><Pencil :size="12" /></button>
              <button title="删除" @click="removeConversation(conversation)"><X :size="13" /></button>
            </div>
          </div>
          <div class="scope-divider"></div>
          <div class="scope-title"><div><span class="kicker">检索范围</span><h3>选择文档</h3></div><small>{{ selectedDocumentIds.length ? `${selectedDocumentIds.length} 项` : '全部' }}</small></div>
          <button class="all-documents" :class="{ active: !selectedDocumentIds.length }" @click="selectAllDocuments"><span class="file-icon"><Library :size="16" /></span><span><strong>全部可用文档</strong><small>自动检索相关片段</small></span><CircleCheckBig v-if="!selectedDocumentIds.length" :size="15" /></button>
          <div class="scope-list"><label v-for="document in readyDocuments" :key="document.id"><input type="checkbox" :checked="selectedDocumentIds.includes(document.id)" @change="toggleDocument(document.id)" /><span class="file-icon"><FileText :size="15" /></span><span><strong>{{ document.name }}</strong><small>{{ document.extension.toUpperCase() }} · {{ formatFileSize(document.size) }}</small></span></label></div>
          <div v-if="!readyDocuments.length" class="scope-empty"><FileWarning :size="24" /><span>暂无可问答文档</span><button @click="selectAndImport">导入文件</button></div>
          <div class="privacy-tip"><ShieldCheck :size="15" /><span>仅发送本地检索命中的文字片段，原文件不会上传。</span></div>
        </aside>
        <div class="chat-panel">
          <header class="chat-toolbar"><div><i :class="{ active: providerConfigured }"></i><strong>{{ activeConversation?.title || (providerConfigured ? providerLabel : '模型未配置') }}</strong><small v-if="providerConfigured">{{ providerConfig.name }} · {{ providerConfig.model }}</small></div><span class="chat-tools"><button v-if="activeConversationId" @click="exportConversation"><Download :size="14" />导出</button><button @click="openProviderDialog"><Settings2 :size="14" />设置</button></span></header>
          <div ref="messageContainer" class="messages">
            <div v-if="!chatMessages.length" class="welcome"><span><MessageCircleQuestion :size="30" /></span><h3>针对文档提问</h3><p>系统先在本地找出相关片段，再交给你配置的模型回答，并标注文件和页码来源。</p><div><button v-for="suggestion in suggestions" :key="suggestion" @click="question=suggestion">{{ suggestion }}</button></div></div>
            <article v-for="message in chatMessages" :key="message.id" class="message" :class="message.role"><span class="avatar"><UserRound v-if="message.role==='user'" :size="16" /><Sparkles v-else :size="16" /></span><div><small>{{ message.role === 'user' ? '你' : 'PanLite AI' }}</small><p>{{ message.content }}</p><div class="message-actions"><button v-if="message.role==='user'" title="编辑这个问题并从这里重新提问" @click="editQuestion(message)"><Edit3 :size="12" />编辑重问</button><button v-else title="复制回答" @click="copyAnswer(message)"><Copy :size="12" />复制</button><button v-if="message.role==='assistant'&&isLastAssistant(message)" title="重新生成最后一个回答" @click="regenerateAnswer"><RotateCcw :size="12" />重新生成</button></div><section v-if="message.citations?.length" class="citations"><details v-for="(citation,index) in message.citations" :key="`${citation.documentId}-${index}`"><summary @click.prevent="openCitation(citation)">[{{ index+1 }}] {{ citation.documentName }} <span>{{ citationLocation(citation) }} · 点击定位</span></summary><p>{{ citation.quote }}</p></details></section></div></article>
            <div v-if="asking" class="thinking"><i></i><i></i><i></i><span>正在流式生成，可随时停止</span></div>
          </div>
          <footer class="composer"><div v-if="editingMessageId" class="editing-tip"><Edit3 :size="12" /><span>正在编辑历史问题；发送后将从这里生成新分支</span><button @click="cancelEdit"><X :size="11" /></button></div><textarea ref="questionInput" v-model="question" rows="2" maxlength="2000" placeholder="询问文档内容，Enter 发送，Shift + Enter 换行" @keydown.enter.exact.prevent="askQuestion"></textarea><div><small>{{ selectedDocumentIds.length ? `仅检索已选 ${selectedDocumentIds.length} 份文档` : `检索全部 ${readyDocuments.length} 份文档` }}</small><button v-if="asking" class="stop-button" @click="stopGeneration"><Square :size="13" />停止</button><button v-else :disabled="!question.trim() || !readyDocuments.length" @click="askQuestion"><Send :size="15" />发送</button></div></footer>
        </div>
      </section>

      <section v-else-if="activeView === 'documents'" class="panel full-panel"><div class="panel-heading"><div><span class="kicker">文档库</span><h3>已导入内容</h3></div><span class="panel-actions"><el-button :disabled="!readyDocuments.length" @click="exportKnowledge"><Download :size="14" />导出知识库</el-button><el-button type="primary" :loading="importing" @click="selectAndImport"><Plus :size="14" />导入</el-button></span></div><div v-if="documents.length" class="document-table"><div class="document-row head"><span>文件</span><span>格式</span><span>大小</span><span>状态</span><span>导入时间</span><span></span></div><div v-for="document in documents" :key="document.id" class="document-row" @click="showDocument(document)"><span class="document-name"><span class="file-icon"><FileText :size="15" /></span><span><strong>{{ document.name }}</strong><small>{{ document.sourceType === 'local' ? '本地文件' : '网盘文件' }}</small></span></span><span class="format-tag">{{ document.extension.toUpperCase() || 'FILE' }}</span><span>{{ formatFileSize(document.size) }}</span><span><i class="status" :class="document.status">{{ statusLabel(document.status) }}</i></span><span>{{ formatDate(document.createdAt) }}</span><span class="row-actions" @click.stop><button title="查看内容" @click="showDocument(document)"><Eye :size="14" /></button><button title="重新解析并重建索引" @click="reindexDocument(document)"><RefreshCw :size="14" /></button><button title="删除记录" @click="removeDocument(document)"><Trash2 :size="14" /></button></span></div></div><div v-else class="empty large"><Library :size="34" /><strong>文档库为空</strong><span>导入后会在这里显示解析和索引状态。</span></div></section>

      <section v-else class="panel full-panel"><div class="panel-heading"><div><span class="kicker">任务中心</span><h3>AI 任务</h3></div><button class="link-button" @click="loadData"><RefreshCw :size="14" />刷新</button></div><div v-if="tasks.length" class="task-list"><article v-for="task in tasks" :key="task.id"><span class="task-icon" :class="task.status"><component :is="task.status==='success'?CircleCheckBig:task.status==='failed'?CircleX:LoaderCircle" :size="17" /></span><div><strong>{{ task.title }}</strong><small>{{ task.message || task.errorMessage || '等待处理' }}</small></div><el-progress :percentage="task.progress" :show-text="false" :stroke-width="6" /><time>{{ formatDate(task.updatedAt) }}</time></article></div><div v-else class="empty large"><ListChecks :size="34" /><strong>暂无 AI 任务</strong></div></section>
    </main>

    <AiProviderDialog v-model="providerVisible" :active-config="providerConfig" @updated="onProviderUpdated" />
    <AiLocalToolsDialog v-model="localToolsVisible" />

    <el-dialog v-model="previewVisible" :title="selectedDocument?.name || '文档详情'" width="660px"><div v-if="selectedDocument"><div class="preview-meta"><span><strong>格式</strong>{{ selectedDocument.extension.toUpperCase() }}</span><span><strong>大小</strong>{{ formatFileSize(selectedDocument.size) }}</span><span><strong>状态</strong>{{ statusLabel(selectedDocument.status) }}</span><span><strong>来源</strong>{{ selectedDocument.sourceType==='local'?'本地导入':'网盘导入' }}</span></div><div v-if="selectedCitationQuote" class="citation-focus"><strong>引用位置</strong><span>{{ selectedCitationLocation }}</span><p>{{ selectedCitationQuote }}</p></div><div v-if="selectedDocument.contentPreview" class="preview"><pre>{{ selectedDocument.contentPreview }}</pre></div><div v-else class="empty"><Puzzle :size="28" /><strong>{{ selectedDocument.status==='awaiting_parser'?'等待对应解析能力包':'没有可预览文本' }}</strong></div></div></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, markRaw, nextTick, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Activity, ArrowRight, BrainCircuit, ChevronRight, CircleCheckBig, CircleX, Copy, Download, Edit3, Eye, FilePlus2, FileSpreadsheet, Files, FileText, FileWarning, Image, Library, ListChecks, LoaderCircle, MessageCircle, MessageCircleQuestion, MessagesSquare, Mic2, PackageOpen, Pencil, Plus, Puzzle, RefreshCw, RotateCcw, Search, Send, Settings2, ShieldCheck, Sparkles, Square, Trash2, UploadCloud, UserRound, Wrench, X } from 'lucide-vue-next'
import { electronApi } from '../api/ipc'
import AiProviderDialog from '../components/AiProviderDialog.vue'
import AiLocalToolsDialog from '../components/AiLocalToolsDialog.vue'
import type { AiAskStreamEvent, AiCitation, AiConversation, AiConversationSearchHit, AiDocument, AiDocumentStatus, AiProviderConfig, AiTask } from '@shared/ai-types'
import { formatFileSize } from '@shared/utils'

type ViewKey = 'overview'|'ask'|'documents'|'tasks'
interface ChatMessage { id:string; role:'user'|'assistant'; content:string; citations?:AiCitation[] }
const activeView=ref<ViewKey>('overview'), importing=ref(false), asking=ref(false), documents=ref<AiDocument[]>([]), tasks=ref<AiTask[]>([]), conversations=ref<AiConversation[]>([]), conversationHits=ref<AiConversationSearchHit[]>([]), conversationSearch=ref(''), activeConversationId=ref(''), activeRequestId=ref(''), pendingAssistantId=ref(''), editingMessageId=ref(''), selectedDocumentIds=ref<string[]>([]), question=ref(''), chatMessages=ref<ChatMessage[]>([]), previewVisible=ref(false), selectedDocument=ref<AiDocument|null>(null), selectedCitationQuote=ref(''), selectedCitationLocation=ref(''), providerVisible=ref(false), localToolsVisible=ref(false)
const messageContainer=ref<HTMLElement>()
const questionInput=ref<HTMLTextAreaElement>()
const providerConfig=reactive<AiProviderConfig>({id:'default',name:'默认模型',type:'openai-compatible',baseUrl:'https://api.openai.com/v1',model:'',transcriptionModel:'gpt-4o-mini-transcribe',embeddingModel:'',hasApiKey:false})
let disposeTaskListener:(()=>void)|undefined, disposeStreamListener:(()=>void)|undefined
const readyDocuments=computed(()=>documents.value.filter(item=>item.status==='ready')), awaitingCount=computed(()=>documents.value.filter(item=>item.status==='awaiting_parser').length), providerConfigured=computed(()=>Boolean(providerConfig.model&&providerConfig.baseUrl)), providerLabel=computed(()=>providerConfig.type==='ollama'?'本地 Ollama':'OpenAI 兼容接口')
const activeConversation=computed(()=>conversations.value.find(item=>item.id===activeConversationId.value))
const displayedConversations=computed(()=>(conversationSearch.value.trim()?conversationHits.value.map(hit=>{const conversation=conversations.value.find(item=>item.id===hit.conversationId);return conversation?{...conversation,snippet:hit.snippet}:null}).filter((item):item is AiConversation&{snippet:string}=>Boolean(item)):conversations.value.map(item=>({...item,snippet:''}))))
const tabs=computed(()=>[{key:'overview' as const,label:'概览',icon:markRaw(Sparkles)},{key:'ask' as const,label:'文档问答',icon:markRaw(MessagesSquare)},{key:'documents' as const,label:'文档库',icon:markRaw(Library),count:documents.value.length},{key:'tasks' as const,label:'AI 任务',icon:markRaw(ListChecks),count:tasks.value.length}])
const suggestions=['总结这些文档的核心内容','列出文档中的关键结论','有哪些重要日期和数字？','比较不同文档的主要观点']
const capabilities=[{name:'文本与数据',description:'提取文本、字幕和常见结构化数据并建立本地索引。',formats:['TXT','MD','CSV','SRT'],icon:markRaw(FileText),available:true},{name:'PDF 文档',description:'按页提取文本层；扫描 PDF 可调用视觉模型 OCR。',formats:['文本 PDF','扫描 PDF'],icon:markRaw(Files),available:true},{name:'Office 文档',description:'新格式原生解析，旧格式优先通过 LibreOffice 高精度转换。',formats:['DOCX/X','XLS/X','PPT/X'],icon:markRaw(FileSpreadsheet),available:true},{name:'图片 OCR',description:'优先使用本地 Tesseract，缺失时回退视觉模型。',formats:['PNG','JPG','WEBP'],icon:markRaw(Image),available:true},{name:'压缩包解析',description:'安全解压后递归解析并建立可选语义索引。',formats:['ZIP','RAR','7Z','TAR'],icon:markRaw(PackageOpen),available:true},{name:'音视频转写',description:'依次尝试外挂字幕、FFmpeg 内嵌字幕、本地 Whisper 和云端转写。',formats:['MP3','MP4','MKV'],icon:markRaw(Mic2),available:true}]
function statusLabel(status:AiDocumentStatus){return({queued:'等待中',processing:'处理中',ready:'已就绪',awaiting_parser:'等待解析器',unsupported:'暂不支持',failed:'失败'} as const)[status]}
function formatDate(value:number){return new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function citationLocation(value:AiCitation){return value.pageNumber?`第 ${value.pageNumber} 页`:value.section||''}
let conversationSearchTimer:ReturnType<typeof setTimeout>|undefined
function searchConversations(){if(conversationSearchTimer)clearTimeout(conversationSearchTimer);const query=conversationSearch.value.trim();if(!query){conversationHits.value=[];return}conversationSearchTimer=setTimeout(async()=>{const result=await electronApi.aiConversationSearch(query);if(result.success&&query===conversationSearch.value.trim())conversationHits.value=result.hits||[]},220)}
function clearConversationSearch(){conversationSearch.value='';conversationHits.value=[]}
function toggleDocument(id:string){selectedDocumentIds.value=selectedDocumentIds.value.includes(id)?selectedDocumentIds.value.filter(item=>item!==id):[...selectedDocumentIds.value,id];void persistDocumentScope()}
function selectAllDocuments(){selectedDocumentIds.value=[];void persistDocumentScope()}
async function scrollMessages(){await nextTick();if(messageContainer.value)messageContainer.value.scrollTop=messageContainer.value.scrollHeight}
async function loadData(){const[d,t,p]=await Promise.all([electronApi.aiDocumentList(),electronApi.aiTaskList(),electronApi.aiProviderGet()]);if(d.success)documents.value=d.documents||[];if(t.success)tasks.value=t.tasks||[];if(p.success&&p.config)Object.assign(providerConfig,p.config);selectedDocumentIds.value=selectedDocumentIds.value.filter(id=>readyDocuments.value.some(doc=>doc.id===id))}
async function loadConversations(selectFirst=false){const result=await electronApi.aiConversationList();if(!result.success)return;conversations.value=result.conversations||[];if(activeConversationId.value&&!conversations.value.some(item=>item.id===activeConversationId.value))activeConversationId.value='';if(selectFirst&&!activeConversationId.value&&conversations.value.length)await selectConversation(conversations.value[0].id)}
async function selectConversation(id:string){if(asking.value){ElMessage.warning('请先停止当前回答');return}const conversation=conversations.value.find(item=>item.id===id);if(!conversation)return;const result=await electronApi.aiConversationMessages(id);if(!result.success){ElMessage.error(result.error||'读取对话失败');return}activeConversationId.value=id;selectedDocumentIds.value=conversation.documentIds.filter(documentId=>readyDocuments.value.some(doc=>doc.id===documentId));chatMessages.value=(result.messages||[]).map(message=>({id:message.id,role:message.role,content:message.content,citations:message.citations}));await scrollMessages()}
async function newConversation(){if(asking.value){ElMessage.warning('请先停止当前回答');return}const result=await electronApi.aiConversationCreate({title:'新对话',documentIds:selectedDocumentIds.value});if(!result.success||!result.conversation){ElMessage.error(result.error||'创建对话失败');return}conversations.value.unshift(result.conversation);activeConversationId.value=result.conversation.id;chatMessages.value=[]}
async function renameConversation(conversation:AiConversation){try{const {value}=await ElMessageBox.prompt('输入新的对话名称','重命名对话',{inputValue:conversation.title,inputPattern:/\S+/,inputErrorMessage:'名称不能为空'});const result=await electronApi.aiConversationRename(conversation.id,value);if(!result.success||!result.conversation)throw new Error(result.error||'重命名失败');await loadConversations()}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error instanceof Error?error.message:String(error))}}
async function removeConversation(conversation:AiConversation){try{await ElMessageBox.confirm(`删除对话“${conversation.title}”及其消息记录？不会删除文档。`,'删除对话',{type:'warning'});const result=await electronApi.aiConversationDelete(conversation.id);if(!result.success)throw new Error(result.error||'删除失败');if(activeConversationId.value===conversation.id){activeConversationId.value='';chatMessages.value=[]}await loadConversations(true)}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error instanceof Error?error.message:String(error))}}
async function persistDocumentScope(){if(!activeConversationId.value)return;const result=await electronApi.aiConversationSetDocuments(activeConversationId.value,selectedDocumentIds.value);if(result.success&&result.conversation){const index=conversations.value.findIndex(item=>item.id===result.conversation?.id);if(index>=0)conversations.value[index]=result.conversation}}
async function ensureConversation(title:string):Promise<string>{if(activeConversationId.value){if(activeConversation.value?.title==='新对话'&&!chatMessages.value.length){const renamed=await electronApi.aiConversationRename(activeConversationId.value,title.slice(0,30));if(renamed.success&&renamed.conversation){const index=conversations.value.findIndex(item=>item.id===renamed.conversation?.id);if(index>=0)conversations.value[index]=renamed.conversation}}return activeConversationId.value}const result=await electronApi.aiConversationCreate({title:title.slice(0,30),documentIds:selectedDocumentIds.value});if(!result.success||!result.conversation)throw new Error(result.error||'创建对话失败');activeConversationId.value=result.conversation.id;conversations.value.unshift(result.conversation);return result.conversation.id}
async function selectAndImport(){importing.value=true;try{const selected=await electronApi.aiSelectFiles();if(!selected.success)throw new Error(selected.error||'选择文件失败');if(!selected.files?.length)return;const result=await electronApi.aiImportFiles(selected.files.map(file=>({localPath:file.localPath,fileName:file.fileName})));if(!result.success)throw new Error(result.error||'导入失败');await loadData();activeView.value='documents';ElMessage.success(`已导入 ${result.documents?.length||0} 个文件`)}catch(error){ElMessage.error(error instanceof Error?error.message:String(error))}finally{importing.value=false}}
async function askQuestion(){const value=question.value.trim();if(!value||asking.value)return;if(!providerConfigured.value){openProviderDialog();ElMessage.warning('请先配置 AI 模型');return}try{const conversationId=await ensureConversation(value);if(editingMessageId.value&&conversationId){const messageIndex=chatMessages.value.findIndex(item=>item.id===editingMessageId.value);const truncated=await electronApi.aiConversationTruncate(conversationId,editingMessageId.value);if(!truncated.success)throw new Error(truncated.error||'无法从选中问题创建新分支');if(messageIndex>=0)chatMessages.value.splice(messageIndex);editingMessageId.value=''}const userId=crypto.randomUUID(),assistantId=crypto.randomUUID();chatMessages.value.push({id:userId,role:'user',content:value},{id:assistantId,role:'assistant',content:''});pendingAssistantId.value=assistantId;question.value='';asking.value=true;activeRequestId.value='';await scrollMessages();const result=await electronApi.aiAskStreamStart({question:value,documentIds:selectedDocumentIds.value,conversationId});if(!result.success||!result.requestId)throw new Error(result.error||'启动回答失败');if(!activeRequestId.value)activeRequestId.value=result.requestId}catch(error){asking.value=false;const index=chatMessages.value.findIndex(item=>item.id===pendingAssistantId.value);if(index>=0&&!chatMessages.value[index].content)chatMessages.value.splice(index,1);ElMessage.error(error instanceof Error?error.message:String(error))}}
function lastMessageIndex(role:'user'|'assistant'){for(let index=chatMessages.value.length-1;index>=0;index--){if(chatMessages.value[index].role===role)return index}return-1}
function isLastAssistant(message:ChatMessage){const index=lastMessageIndex('assistant');return message.role==='assistant'&&index>=0&&chatMessages.value[index].id===message.id}
async function copyAnswer(message:ChatMessage){try{await navigator.clipboard.writeText(message.content);ElMessage.success('回答已复制')}catch{ElMessage.error('复制失败，请手动选择文本')}}
async function editQuestion(message:ChatMessage){if(asking.value)return;editingMessageId.value=message.id;question.value=message.content;await nextTick();questionInput.value?.focus()}
function cancelEdit(){editingMessageId.value='';question.value=''}
async function regenerateAnswer(){if(asking.value||!activeConversationId.value)return;const userIndex=lastMessageIndex('user'),assistantIndex=lastMessageIndex('assistant');const lastUser=userIndex>=0?chatMessages.value[userIndex]:undefined;if(!lastUser||assistantIndex<0)return;const assistantId=crypto.randomUUID();chatMessages.value.splice(assistantIndex,1,{id:assistantId,role:'assistant',content:''});pendingAssistantId.value=assistantId;asking.value=true;activeRequestId.value='';await scrollMessages();try{const result=await electronApi.aiAskStreamStart({question:lastUser.content,documentIds:selectedDocumentIds.value,conversationId:activeConversationId.value,regenerate:true});if(!result.success||!result.requestId)throw new Error(result.error||'重新生成失败');if(!activeRequestId.value)activeRequestId.value=result.requestId}catch(error){asking.value=false;chatMessages.value[assistantIndex].content=`重新生成失败：${error instanceof Error?error.message:String(error)}`}}
async function stopGeneration(){if(!activeRequestId.value)return;const result=await electronApi.aiAskStreamCancel(activeRequestId.value);if(!result.success)ElMessage.warning(result.error||'回答已经结束')}
async function handleStreamEvent(event:AiAskStreamEvent){if(!asking.value)return;if(!activeRequestId.value)activeRequestId.value=event.requestId;if(event.requestId!==activeRequestId.value)return;const message=chatMessages.value.find(item=>item.id===pendingAssistantId.value);if(event.type==='delta'&&message&&event.delta){message.content+=event.delta;await scrollMessages();return}if(event.type==='completed'&&message){message.content=event.answer||message.content;message.citations=event.citations||[]}if(event.type==='error'){if(message&&!message.content)message.content=`生成失败：${event.error||'未知错误'}`;ElMessage.error(event.error||'生成失败')}if(event.type==='cancelled'){if(message)message.content=`${message.content}${message.content?'\n\n':''}[已停止生成]`;ElMessage.info('已停止生成')}if(['completed','error','cancelled'].includes(event.type)){asking.value=false;activeRequestId.value='';pendingAssistantId.value='';await Promise.all([loadData(),loadConversations()]);if(activeConversationId.value&&event.type==='completed')await selectConversation(activeConversationId.value);await scrollMessages()}}
function openProviderDialog(){providerVisible.value=true}
function onProviderUpdated(config:AiProviderConfig){Object.assign(providerConfig,config)}
function showDocument(document:AiDocument){selectedCitationQuote.value='';selectedCitationLocation.value='';selectedDocument.value=document;previewVisible.value=true}
function openCitation(citation:AiCitation){const document=documents.value.find(item=>item.id===citation.documentId);if(!document){ElMessage.warning('引用文档已经被删除');return}selectedDocument.value=document;selectedCitationQuote.value=citation.quote;selectedCitationLocation.value=citationLocation(citation);previewVisible.value=true}
async function exportConversation(){if(!activeConversationId.value)return;const result=await electronApi.aiConversationExport(activeConversationId.value);if(!result.success)ElMessage.error(result.error||'导出失败');else if(!result.canceled)ElMessage.success('对话已导出为 Markdown')}
async function exportKnowledge(){const result=await electronApi.aiKnowledgeExport();if(!result.success)ElMessage.error(result.error||'知识库导出失败');else if(!result.canceled)ElMessage.success('完整知识库已导出为 Markdown')}
async function reindexDocument(document:AiDocument){try{const result=await electronApi.aiDocumentReindex(document.id);if(!result.success)throw new Error(result.error||'重建索引失败');await loadData();ElMessage.success('文档已重新解析并重建索引')}catch(error){ElMessage.error(error instanceof Error?error.message:String(error))}}
async function removeDocument(document:AiDocument){try{await ElMessageBox.confirm(`只删除 AI 工作台中的“${document.name}”记录和本地索引，不会删除原文件。`,'删除导入记录',{type:'warning'});const result=await electronApi.aiDocumentDelete(document.id);if(!result.success)throw new Error(result.error||'删除失败');await loadData();ElMessage.success('已删除 AI 导入记录')}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error instanceof Error?error.message:String(error))}}
onMounted(async()=>{await loadData();await loadConversations(true);disposeTaskListener=electronApi.onAiTaskUpdated(task=>{const index=tasks.value.findIndex(item=>item.id===task.id);if(index>=0)tasks.value[index]=task;else tasks.value.unshift(task)});disposeStreamListener=electronApi.onAiAskStreamEvent(event=>{void handleStreamEvent(event)})});onUnmounted(()=>{disposeTaskListener?.();disposeStreamListener?.();if(conversationSearchTimer)clearTimeout(conversationSearchTimer);if(activeRequestId.value)void electronApi.aiAskStreamCancel(activeRequestId.value)})
</script>

