.conversation-search{height:30px;display:flex;align-items:center;gap:6px;margin-bottom:6px;padding:0 8px;border:1px solid #e0e6ee;border-radius:8px;color:#8a95a6;background:#fff}.conversation-search input{min-width:0;flex:1;border:0;outline:0;color:#46546a;background:transparent;font-size:10px}.conversation-search>svg:last-child{cursor:pointer}.conversation-main span{display:flex;min-width:0;flex-direction:column}.conversation-main small{margin-top:1px;overflow:hidden;text-overflow:ellipsis;color:#8c97a7;font-size:8px;font-weight:400}.chat-tools{display:flex;align-items:center;gap:10px}.chat-tools button{display:flex;align-items:center;gap:5px;border:0;color:#5573aa;background:transparent;cursor:pointer}.citation-focus{margin-top:12px;padding:11px;border:1px solid #cbdaf2;border-radius:10px;background:#f0f5ff}.citation-focus strong{color:#3f67b1}.citation-focus span{margin-left:8px;color:#72829a;font-size:10px}.citation-focus p{margin-top:6px;color:#55647a;font-size:10px;line-height:1.6}.document-row,.task-list article{content-visibility:auto;contain-intrinsic-size:auto 56px}
.message-actions{display:flex;gap:5px;margin-top:5px;opacity:0;transition:opacity .15s}.message:hover .message-actions,.message:focus-within .message-actions{opacity:1}.message.user .message-actions{justify-content:flex-end}.message-actions button{display:flex;align-items:center;gap:4px;padding:3px 6px;border:0;border-radius:6px;color:#738197;background:transparent;cursor:pointer;font-size:9px}.message-actions button:hover{color:#3566bb;background:#edf3ff}.editing-tip{display:flex;align-items:center;gap:6px;margin-bottom:6px;padding:5px 7px;border-radius:7px;color:#725d2f;background:#fff7e5;font-size:9px}.editing-tip span{flex:1}.editing-tip button{width:22px;height:22px!important;padding:0!important;display:grid!important;place-items:center;background:transparent!important;color:#88734a!important}.panel-actions{display:flex;align-items:center;gap:7px}
